// === Tab: mySketch ===
// by SamuelYAN
// more works //
   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/

let mySize;
let seed = Math.random() * 2000;
let tile_count = 12;
let speed = 5;

// colors
let colors1 = "ffbe00-ffd675-000000"
  .split("-")
  .map((a) => "#" + a);
let colors2 = "7d483e-b87644-e6d2c9-e45e00-905c40"
  .split("-")
  .map((a) => "#" + a);

let squares;

function setup() {
  // pixelDensity(5);
  mySize = max(windowWidth, windowHeight);
  createCanvas(mySize, mySize);
  randomSeed(seed);
  noStroke();
	fill("#ffbe00");
	rect(0,0,width,height);
  addSquares();
}

function draw() {
  randomSeed(seed);
  for (let s of squares) {
    //s.update();
    s.run();
  }
}

// easeIN and OUT 01 for roll
function easeOut(t) {
  return 1 - sq(t);
}

// easeIN and OUT 02 for move
function easeInOutSquare(t) {
  if ((t /= 0.5) < 1) {
    return 0.5 * sq(sq(t));
  } else {
    return 0.5 * ((t -= 2) * sq(t) + 2);
  }
}

//
function addSquares() {
  squares = [];

  let w = mySize / tile_count;
  for (let i = 0; i < tile_count; i++) {
    for (let j = 0; j < tile_count; j++) {
      let x = i * w;
      let y = j * w;
      squares.push(new makeSquare(x, y, w));
    }
  }
}

class makeSquare {
  constructor(x, y, w) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.col1 = random(colors1);
    this.col2 = random(colors1);
    this.colLine = random(colors1);
    this.settime();
    this.dir = random() < 0.5 ? -2 : 2;
    this.speed = 0;
    this.ang = (int(random(4)) * TAU) / 3;
    this.strWei = 2;
    this.tog = 0;
    this.move = (this.w / 8) * 2.5;
    this.moveS1 = this.w;
    this.movePlus = this.move * 2;
    this.moveS2 = this.w + this.movePlus;
    this.moveX = (this.movePlus)  * sin(PI / 4);
    this.moveY = (this.movePlus)  * cos(PI / 4);
    this.scaleAll = 1;
  }

  display() {
    //破線の四方形
    push();
    translate(this.x + this.moveS1 / 2, this.y + this.moveS1 / 2);
    scale(this.scaleAll);
    strokeCap(PROJECT);
    stroke(this.col1);
    noFill();
    strokeWeight(this.strWei/2);
    this.newW = this.w / 2;
    drawingContext.setLineDash([2, 8]);
    rectMode(CENTER);
    square(0, 0, this.newW);
    pop();

    //繋ぐ線たち
    push();
    translate(this.x + this.moveS1 / 2, this.y + this.moveS1 / 2);
    scale(this.scaleAll);
    strokeCap(SQUARE);
    stroke(this.colLine);
    strokeWeight(this.strWei / 4);
    noFill();

    line(
      -this.newW / 2,
      -this.newW / 2,
      -this.newW / 2 + this.moveX + this.move,
      -this.newW / 2 + this.moveY + this.move
    );
    line(
      this.newW / 2,
      -this.newW / 2,
      this.newW / 2 + this.moveX + this.move,
      -this.newW / 2 + this.moveY + this.move
    );
    line(
      this.newW / 2,
      this.newW / 2,
      this.newW / 2 + this.moveX + this.move,
      this.newW / 2 + this.moveY + this.move
    );
    line(
      -this.newW / 2,
      this.newW / 2,
      -this.newW / 2 + this.moveX + this.move,
      this.newW / 2 + this.moveY + this.move
    );
    pop();

    //色の四方形
    push();
    translate(this.x + this.moveS2 / 2, this.y + this.moveS2 / 2);
    scale(this.scaleAll);
    stroke(this.col2);
    fill(this.col2);
    strokeWeight(this.strWei);
    this.newW = this.w / 2;
    rectMode(CENTER);
    square(this.move, this.move, this.newW);
    pop();
  }

  settime() {
    this.t = -int(random(map(speed, 1, 5, 3000, 100)));
    this.t1 = map(speed, 1, 5, 400, 100);
  }

  update() {
    //this.settime();
    if (this.t >= 0 && this.t < this.t1) {
      let easePar = norm(this.t, 0, this.t1 - 1);
      this.move =
        ((lerp(-2.5, 2.5, easeInOutSquare(easePar)) * this.w) / 8) *
        (this.tog * 2 - 1);
    }
    if (this.t1 < this.t) {
      if (this.tog) this.tog = 0;
      else this.tog = 1;
      this.settime();
    }
    this.t++;
  }

  run() {
    //this.settime();
    this.update();
    this.display();
  }
}

function mouseClicked() {
  seed = Math.random() * 1000;
  randomSeed(seed);
  //background(245);
  loop();
}

function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop();
    saveCanvas("MovingShapes-bySamuel", "png");
  }
}

